const config: runtime.GetPrismaClientConfig = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// Lean OEM-catalog schema — hosted in its own Supabase project\n// (rtzcrngduscrhgozrojv, BojoIndAI1's Org, free tier).\n//\n// Design goals:\n//   • Canonical Part catalog (~35K rows) — partNumber is unique, aliases[]\n//     covers legacy & cross-references. Replaces the denormalized OemPart\n//     \"BOM line\" rows in the Dyvika prod DB.\n//   • Narrow PartLine junction (~1.5M rows) — just (diagramId, partId,\n//     callout, qty, notes). No part metadata duplicated here.\n//   • Machine + MachineRevision unified for numeric-rev (small construction)\n//     and serial-range (big-equipment) catalogs. Mode flag tells which.\n//   • Diagram == an assembly drawing with click-hotspots. Image bytes live\n//     in Supabase Storage; this table only carries the storage key.\n//   • Accessories represented as separate Machine rows with parentMachineId.\n//\n// Reads are driven from a second Prisma client in the Dyvika app:\n//   import { PrismaClient as OemPrismaClient } from \"@/app/generated/oem-prisma\"\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../../src/app/generated/oem-prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  // URLs supplied via prisma/oem/prisma.config.ts (Prisma 7 mandates config-file\n  // datasource URLs). Pass --config prisma/oem/prisma.config.ts to all\n  // OEM-related prisma CLI commands.\n}\n\n// ─── Enums ────────────────────────────────────────────────────────────────────\n\n/// Where a piece of data originated. Tells the storefront which renderer +\n/// what fields to trust on each row.\nenum OemCatalogSource {\n  EPARTS_API // shop.wackerneuson.com /ws/v2/amd/*\n  PDF // factory parts-book PDFs extracted via pdfplumber/fitz\n  WEIDEMANN_ESERVICE // service.weidemann.de — dealer-gated agricultural BOMs\n  LSENGINEERS // lsengineers.co.uk Magento BOMs (big-equipment fill)\n  MANUAL // hand-entered fallback\n}\n\n/// Distinguishes the two revision styles WN uses across categories. Small\n/// construction has numeric revs (\"108\"); big equipment uses WNC serial-range\n/// books (\"WNCE2401K00000140 — ...\"). Some machines have both.\nenum RevisionMode {\n  NUMERIC // revisionTag = \"108\", \"107\", ...\n  SERIAL_RANGE // revisionTag = \"WNCE2401K00000140 — WNCE2401K00009999\" etc.\n}\n\n/// Listing source for the per-SKU enrichment table (Neyer/LS Engineers/etc.).\nenum ListingSource {\n  NEYER_EN\n  NEYER_DE\n  LSENGINEERS\n  WEIDEMANN_ESERVICE\n  OTHER\n}\n\n/// Compatibility / fitment source.\nenum CompatSource {\n  DHS\n  LSENGINEERS\n  EPARTS_API\n  MANUAL\n}\n\n// ─── Machines ─────────────────────────────────────────────────────────────────\n\n/// A machine in the OEM catalog. Multiple Machine rows can share a\n/// `modelName` (\"EZ38\" has many SAP machine-numbers, each a separate row).\n/// Accessory machines (e.g. HPU8 hydraulic power unit) carry parentMachineId\n/// pointing at the host machine — they have their own BOM but are exposed\n/// from the parent's dropdown in eParts.\nmodel Machine {\n  id String @id @default(cuid())\n\n  /// Source-side identity (SAP machine number for eParts, internal slug\n  /// for LS Engineers / Weidemann / manual).\n  code   String\n  source OemCatalogSource\n\n  /// Display name as the source published it (may include trailing SAP code\n  /// or category words, e.g. \"803 Excavator,Track,ROP's,DPU\").\n  displayName String\n\n  /// Canonical model token — lowercased, no separators\n  /// (e.g. \"ez38\", \"th627\", \"bpu2540aus\"). Primary join key across sources\n  /// when SAP code isn't comparable (LS↔eParts).\n  modelName String\n\n  /// Category breadcrumb from the source catalog. JSON array of strings.\n  /// e.g. [\"Excavators\",\"Tracked Excavators\",\"Tracked Conventional Tail\"].\n  categoryPath Json?\n\n  /// Parent machine when this is an accessory exposed under another machine\n  /// (e.g. HPU8 hydraulic power unit under 803). Self-referential nullable\n  /// FK; cascade-detach on parent delete (keep accessory rows).\n  parentMachineId String?\n  parentMachine   Machine?  @relation(\"MachineAccessories\", fields: [parentMachineId], references: [id], onDelete: SetNull)\n  accessories     Machine[] @relation(\"MachineAccessories\")\n\n  /// Primary image URL — Supabase Storage key OR remote URL. Filled lazily.\n  primaryImageUrl String?\n\n  /// Free-form metadata blobs from the source — kept as JSON to absorb\n  /// source-specific fields without schema churn.\n  summary     String?\n  description String?\n  brochures   Json?\n\n  /// Discontinued / current flag from the source (\"Current Products\"\n  /// vs \"Discontinued Products\" in eParts facets).\n  isDiscontinued Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  revisions    MachineRevision[]\n  partListings PartListing[]\n  compats      PartCompatibility[]\n\n  @@unique([code, source])\n  @@index([modelName])\n  @@index([parentMachineId])\n}\n\n/// One revision of a Machine. A revision is the BOM-identity unit — its\n/// `sparePartListCode` is what the eParts dropdown returns as the canonical\n/// parts-book code. Diagrams hang off MachineRevision.\n///\n/// Multiple revisions can share a `sparePartListCode` (means same BOM,\n/// different production runs) — we still create separate rows for traceability\n/// but the diagrams below are physically the same drawings.\nmodel MachineRevision {\n  id        String @id @default(cuid())\n  machineId String\n\n  /// Source identifier for the revision: \"108\" (numeric) or \"AF00894\"\n  /// (production identifier) — display only.\n  revisionTag String\n\n  /// Numeric (small construction) vs serial-range (big equipment).\n  mode RevisionMode\n\n  /// BOM identity from eParts: sparepartsBookList[].code. Multiple revisions\n  /// may share this (BOM-stable); some have unique codes per revision.\n  sparePartListCode String?\n\n  /// Whether the source claims this revision has a BOM tree (vs operating\n  /// manuals only). From eParts: revisions[].hasBomTree.\n  hasBom Boolean @default(false)\n\n  /// Production-identifier range, if exposed (big-equipment only).\n  afCode String? // e.g. \"AF00894\"\n  aiCode String? // e.g. \"AI00500\"\n\n  /// WNC serial-number range — primary identifier for big-equipment\n  /// revisions. NULL on numeric-rev machines.\n  serialFrom String? // e.g. \"WNCE2401K00000140\"\n  serialTo   String? // e.g. \"WNCE2401K00009999\", or NULL for open-ended\n\n  /// Free-form revision name as the source published it (often the entire\n  /// \"EZ38 (AF00894/AI00500 - ...) (WNCE0702NPAL00160 - ...)\" string).\n  rawName String?\n\n  /// Which catalog source provided this revision's BOM data.\n  bomSource OemCatalogSource?\n\n  /// PDF and image artefacts associated with the revision.\n  imageUrl            String?\n  partsManualUrl      String?\n  partsManualFilename String?\n  operatingManuals    Json? // [{lang, url, filename, size}]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  machine  Machine   @relation(fields: [machineId], references: [id], onDelete: Cascade)\n  diagrams Diagram[]\n\n  @@unique([machineId, revisionTag])\n  @@index([machineId])\n  @@index([sparePartListCode])\n  @@index([serialFrom])\n}\n\n// ─── Diagrams ─────────────────────────────────────────────────────────────────\n\n/// One assembly diagram (= eParts component / PDF page).\nmodel Diagram {\n  id         String @id @default(cuid())\n  revisionId String\n\n  /// Sort order from the source (eParts position field).\n  position Int?\n\n  /// Human name of the assembly, e.g. \"Vibration Plate\", \"Engine GX160\".\n  name String\n\n  /// Stable cross-ref into the source catalog. For eParts this is\n  /// subProductCode; lets us re-fetch the same component without re-walking.\n  componentCode String?\n\n  /// Per-component revision (distinct from parent MachineRevision).\n  revisionLevel String?\n\n  /// When the diagram lives under a named sub-revision in the source\n  /// (e.g. \"Engine GX160\" as a sub-tree of revision 108). Null for top-level.\n  subRevisionName String?\n\n  /// Storage key for the diagram PNG. Empty until we run the upload phase.\n  /// During transition this can hold a remote URL.\n  diagramImageKey      String?\n  /// Original source media id (Hybris reference) — useful for re-fetch.\n  diagramImageSourceId String?\n\n  /// `.hd3` click-hotspots inlined ({calloutId → rect}). Drives the\n  /// interactive parts viewer. Typical size ~1 KB.\n  hotspotsJson Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  revision MachineRevision @relation(fields: [revisionId], references: [id], onDelete: Cascade)\n  lines    PartLine[]\n\n  @@unique([revisionId, componentCode])\n  @@index([revisionId])\n  @@index([componentCode])\n}\n\n// ─── Parts ────────────────────────────────────────────────────────────────────\n\n/// Canonical part catalog — one row per physical part identity.\n/// `aliases[]` collects every alternate code that points at this part\n/// (legacy 7-digit SAP, cross-references from retailer SKUs, etc.).\n///\n/// Search by either modern or legacy number:\n///   WHERE partNumber = $1 OR $1 = ANY(aliases)\nmodel Part {\n  id String @id @default(cuid())\n\n  /// Canonical part number — modern 10-digit form preferred when known.\n  partNumber String @unique\n\n  /// Every other code we've seen for this part. Includes the legacy\n  /// 7-digit form (mined from sku_legacy_modern_map.json) plus any\n  /// retailer cross-references and source variants.\n  aliases String[] @default([])\n\n  /// Canonical part name. Sourced from the first non-null name across\n  /// all BOM appearances of this part.\n  name String\n\n  /// \"PC\", \"KG\", \"M\", etc. Null when the source doesn't specify.\n  unitOfMeasure String?\n\n  /// True if ANY source marked this part as a recommended-spare.\n  isRecommended Boolean @default(false)\n\n  /// Sources that have data for this part (EPARTS_API, PDF, LSENGINEERS,\n  /// etc.) — for ranking + diagnostics.\n  sources OemCatalogSource[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  lines    PartLine[]\n  listings PartListing[]\n  prices   PartPriceSnapshot[]\n  compats  PartCompatibility[]\n\n  @@index([aliases], type: Gin)\n  @@index([name])\n}\n\n/// BOM line — junction between Diagram (assembly) and Part. Narrow:\n/// no part metadata duplicated here, only the appearance-specific fields.\nmodel PartLine {\n  diagramId String\n  partId    String\n\n  /// Callout number on the diagram (e.g. \"1\", \"3\", \"6a\"). Pairs with the\n  /// id field inside the parent Diagram's hotspotsJson.\n  callout String @default(\"\")\n\n  qty   Int?\n  notes String?\n\n  /// Set when the source flagged this line as a recommended spare.\n  /// (Only the older alfis-format PDFs and some sources convey this.)\n  isRecommended Boolean @default(false)\n\n  diagram Diagram @relation(fields: [diagramId], references: [id], onDelete: Cascade)\n  part    Part    @relation(fields: [partId], references: [id], onDelete: Cascade)\n\n  @@id([diagramId, partId, callout])\n  @@index([partId])\n  @@index([diagramId])\n}\n\n// ─── External-source enrichment ───────────────────────────────────────────────\n\n/// Rich per-SKU data sourced from external retailers that publish more than\n/// just SKU + price. Currently: Neyer (~45K Wacker products with description,\n/// HD images, replaces[], weight, etc.) and LS Engineers (~21K BOM-derived\n/// SKUs with title, price, lead time).\n///\n/// Each Part can have multiple listings — one per source. Optional Machine\n/// link when the listing was discovered in a model-specific context (LS\n/// Engineers always provides this; Neyer rarely does).\nmodel PartListing {\n  id     String        @id @default(cuid())\n  partId String\n  source ListingSource\n\n  /// SKU as the source publishes it (may equal partNumber or be a wrapper).\n  externalSku String\n  externalUrl String\n\n  title       String?\n  description String?\n  imageUrls   Json? // string[]\n  priceText   String?\n  priceAmount String? // decimal as string to avoid rounding\n  currency    String? @default(\"USD\")\n  leadTime    String?\n\n  /// \"Replaces\" cross-references the source publishes — populated into\n  /// the Part.aliases array during ingest, kept here for traceability.\n  replacesOem String[] @default([])\n\n  /// When the listing was discovered in a model-specific context.\n  machineId String?\n\n  scrapedAt DateTime @default(now())\n\n  part    Part     @relation(fields: [partId], references: [id], onDelete: Cascade)\n  machine Machine? @relation(fields: [machineId], references: [id], onDelete: SetNull)\n\n  @@unique([source, externalSku])\n  @@index([partId])\n  @@index([machineId])\n}\n\n/// Fitment / compatibility: which Machines does a Part fit?  Sourced from\n/// DHS Compatibility & Fitment tables, LS Engineers `fits_models`, and\n/// implicitly from eParts BOM rows.\n///\n/// Note: NOT a hard FK to Machine (only to Part) because compatibility data\n/// often references model NAMES that don't exactly match a Machine.modelName\n/// — we keep the modelName text for fuzzy matching at read time.\nmodel PartCompatibility {\n  id     String @id @default(cuid())\n  partId String\n\n  /// Canonical model token (lowercased, separator-stripped) — same shape\n  /// as Machine.modelName so joins are clean.\n  modelName String\n\n  /// Optional more-specific machine link (when source published a serial\n  /// or SAP code). Nullable + ON DELETE SET NULL so unmatched data survives.\n  machineId String?\n\n  source CompatSource\n\n  scrapedAt DateTime @default(now())\n\n  part    Part     @relation(fields: [partId], references: [id], onDelete: Cascade)\n  machine Machine? @relation(fields: [machineId], references: [id], onDelete: SetNull)\n\n  @@unique([partId, modelName, source])\n  @@index([partId])\n  @@index([modelName])\n  @@index([machineId])\n}\n\n/// Retailer pricing snapshots (admin-only, not exposed to the storefront).\n/// Captured by the scraper pipeline (hydrotech / dhs-klevu / russopower /\n/// danseusa / tmsequip / contractorsdirect / lsengineers).\n///\n/// `partNumber` is text, NOT a FK to Part — retailers carry SKUs we\n/// haven't yet ingested. After enough scrapes the partId can be backfilled.\nmodel PartPriceSnapshot {\n  id         String  @id @default(cuid())\n  partNumber String\n  partId     String? // backfilled when the SKU is recognised\n\n  retailer       String\n  currency       String  @default(\"USD\")\n  price          String? // text to avoid rounding; admin tools cast to Decimal\n  productName    String?\n  productUrl     String?\n  imageUrl       String?\n  isCallForPrice Boolean @default(false)\n\n  scrapedAt DateTime @default(now())\n\n  part Part? @relation(fields: [partId], references: [id], onDelete: SetNull)\n\n  @@index([partNumber])\n  @@index([partId])\n  @@index([retailer, scrapedAt])\n}\n",
  "runtimeDataModel": {
    "models": {},
    "enums": {},
    "types": {}
  },
  "parameterizationSchema": {
    "strings": [],
    "graph": ""
  }
}

